-- 1. EXTENSIONS & PREREQUISITES
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- 2. CUSTOM ENUM TYPES
DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'student_gender') THEN
        CREATE TYPE "student_gender" AS ENUM ('MALE', 'FEMALE', 'OTHER');
    END IF;
END $$;

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'student_status') THEN
        CREATE TYPE "student_status" AS ENUM ('ACTIVE', 'SUSPENDED', 'GRADUATED', 'DROPOUT');
    END IF;
END $$;

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'enrollment_status') THEN
        CREATE TYPE "enrollment_status" AS ENUM ('IN_PROGRESS', 'PASSED', 'FAILED', 'WITHDRAWN');
    END IF;
END $$;

-- 3. AUDIT TRIGGER FUNCTION FOR updated_at
CREATE OR REPLACE FUNCTION trigger_set_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 4. TABLE DEFINITIONS (Topologically Sorted for Referential Integrity)

-- Table: departments (Khoa / Vien dao tao quan ly cac nganh va lop hoc)
CREATE TABLE IF NOT EXISTS "departments" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "department_code" VARCHAR(30) NOT NULL UNIQUE,
    "name" VARCHAR(150) NOT NULL,
    "description" TEXT,
    "is_active" BOOLEAN NOT NULL DEFAULT TRUE
);
COMMENT ON TABLE "departments" IS 'Khoa / Vien dao tao quan ly cac nganh va lop hoc';
COMMENT ON COLUMN "departments"."id" IS 'Unique surrogate primary key (UUIDv4/v7)';
COMMENT ON COLUMN "departments"."created_at" IS 'Timestamp when record was created';
COMMENT ON COLUMN "departments"."updated_at" IS 'Timestamp when record was last updated';
COMMENT ON COLUMN "departments"."deleted_at" IS 'Soft-delete timestamp; NULL indicates active record';
COMMENT ON COLUMN "departments"."version" IS 'Optimistic locking version counter';
COMMENT ON COLUMN "departments"."department_code" IS 'Ma khoa duy nhat (VD: CNTT, DTVT)';
COMMENT ON COLUMN "departments"."name" IS 'Ten day du cua khoa';
COMMENT ON COLUMN "departments"."description" IS 'Mo ta chuc nang nhiem vu khoa';
COMMENT ON COLUMN "departments"."is_active" IS 'Trang thai hoat dong';
DROP TRIGGER IF EXISTS "trg_departments_updated_at" ON "departments";
CREATE TRIGGER "trg_departments_updated_at"
BEFORE UPDATE ON "departments"
FOR EACH ROW EXECUTE FUNCTION trigger_set_timestamp();

-- Table: classes (Lop sinh hoat hoc tap theo nien khoa)
CREATE TABLE IF NOT EXISTS "classes" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "class_code" VARCHAR(30) NOT NULL UNIQUE,
    "name" VARCHAR(150) NOT NULL,
    "department_id" UUID NOT NULL,
    "academic_year" VARCHAR(30) NOT NULL,
    "is_active" BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT "fk_classes_department" FOREIGN KEY ("department_id") REFERENCES "departments" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
COMMENT ON TABLE "classes" IS 'Lop sinh hoat hoc tap theo nien khoa';
COMMENT ON COLUMN "classes"."id" IS 'Unique surrogate primary key (UUIDv4/v7)';
COMMENT ON COLUMN "classes"."created_at" IS 'Timestamp when record was created';
COMMENT ON COLUMN "classes"."updated_at" IS 'Timestamp when record was last updated';
COMMENT ON COLUMN "classes"."deleted_at" IS 'Soft-delete timestamp; NULL indicates active record';
COMMENT ON COLUMN "classes"."version" IS 'Optimistic locking version counter';
COMMENT ON COLUMN "classes"."class_code" IS 'Ma lop duy nhat (VD: D20CNTT1)';
COMMENT ON COLUMN "classes"."name" IS 'Ten lop sinh hoat';
COMMENT ON COLUMN "classes"."department_id" IS 'Tham chieu toi khoa quan ly';
COMMENT ON COLUMN "classes"."academic_year" IS 'Nien khoa (VD: 2020-2025)';
COMMENT ON COLUMN "classes"."is_active" IS 'Trang thai lop';
DROP TRIGGER IF EXISTS "trg_classes_updated_at" ON "classes";
CREATE TRIGGER "trg_classes_updated_at"
BEFORE UPDATE ON "classes"
FOR EACH ROW EXECUTE FUNCTION trigger_set_timestamp();

-- Table: courses (Hoc phan chuong trinh dao tao)
CREATE TABLE IF NOT EXISTS "courses" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "course_code" VARCHAR(30) NOT NULL UNIQUE,
    "name" VARCHAR(200) NOT NULL,
    "credits" INTEGER NOT NULL DEFAULT 3 CHECK (credits > 0),
    "department_id" UUID NOT NULL,
    CONSTRAINT "fk_courses_department" FOREIGN KEY ("department_id") REFERENCES "departments" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
COMMENT ON TABLE "courses" IS 'Hoc phan chuong trinh dao tao';
COMMENT ON COLUMN "courses"."id" IS 'Unique surrogate primary key (UUIDv4/v7)';
COMMENT ON COLUMN "courses"."created_at" IS 'Timestamp when record was created';
COMMENT ON COLUMN "courses"."updated_at" IS 'Timestamp when record was last updated';
COMMENT ON COLUMN "courses"."deleted_at" IS 'Soft-delete timestamp; NULL indicates active record';
COMMENT ON COLUMN "courses"."version" IS 'Optimistic locking version counter';
COMMENT ON COLUMN "courses"."course_code" IS 'Ma mon hoc (VD: INT1306)';
COMMENT ON COLUMN "courses"."name" IS 'Ten mon hoc';
COMMENT ON COLUMN "courses"."credits" IS 'So tin chi';
COMMENT ON COLUMN "courses"."department_id" IS 'Khoa phu trach mon hoc';
DROP TRIGGER IF EXISTS "trg_courses_updated_at" ON "courses";
CREATE TRIGGER "trg_courses_updated_at"
BEFORE UPDATE ON "courses"
FOR EACH ROW EXECUTE FUNCTION trigger_set_timestamp();

-- Table: students (Ho so thong tin sinh vien day du kem anh dai dien)
CREATE TABLE IF NOT EXISTS "students" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "student_code" VARCHAR(30) NOT NULL UNIQUE,
    "full_name" VARCHAR(150) NOT NULL,
    "gender" VARCHAR(10) NOT NULL DEFAULT 'OTHER' CHECK (gender IN ('MALE', 'FEMALE', 'OTHER')),
    "dob" DATE,
    "email" VARCHAR(255) NOT NULL UNIQUE,
    "phone_number" VARCHAR(30),
    "address" TEXT,
    "avatar_url" VARCHAR(500),
    "class_id" UUID NOT NULL,
    "status" VARCHAR(30) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'SUSPENDED', 'GRADUATED', 'DROPOUT')),
    CONSTRAINT "fk_students_class" FOREIGN KEY ("class_id") REFERENCES "classes" ("id") ON DELETE RESTRICT ON UPDATE CASCADE,
    CONSTRAINT "chk_students_email_format" CHECK (email ~* '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$')
);
COMMENT ON TABLE "students" IS 'Ho so thong tin sinh vien day du kem anh dai dien';
COMMENT ON COLUMN "students"."id" IS 'Unique surrogate primary key (UUIDv4/v7)';
COMMENT ON COLUMN "students"."created_at" IS 'Timestamp when record was created';
COMMENT ON COLUMN "students"."updated_at" IS 'Timestamp when record was last updated';
COMMENT ON COLUMN "students"."deleted_at" IS 'Soft-delete timestamp; NULL indicates active record';
COMMENT ON COLUMN "students"."version" IS 'Optimistic locking version counter';
COMMENT ON COLUMN "students"."student_code" IS 'Ma so sinh vien duy nhat (VD: B20DCCN001)';
COMMENT ON COLUMN "students"."full_name" IS 'Ho va ten day du cua sinh vien';
COMMENT ON COLUMN "students"."gender" IS 'Gioi tinh sinh vien';
COMMENT ON COLUMN "students"."dob" IS 'Ngay thang nam sinh';
COMMENT ON COLUMN "students"."email" IS 'Email lien he chinh thuc';
COMMENT ON COLUMN "students"."phone_number" IS 'So dien thoai di dong';
COMMENT ON COLUMN "students"."address" IS 'Dia chi thuong tru hoac cu tru';
COMMENT ON COLUMN "students"."avatar_url" IS 'Duong dan luu anh dai dien upload';
COMMENT ON COLUMN "students"."class_id" IS 'Tham chieu toi lop sinh hoat';
COMMENT ON COLUMN "students"."status" IS 'Trang thai hoc tap';
DROP TRIGGER IF EXISTS "trg_students_updated_at" ON "students";
CREATE TRIGGER "trg_students_updated_at"
BEFORE UPDATE ON "students"
FOR EACH ROW EXECUTE FUNCTION trigger_set_timestamp();

-- Table: enrollments (Dang ky hoc phan va bang diem sinh vien)
CREATE TABLE IF NOT EXISTS "enrollments" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted_at" TIMESTAMPTZ,
    "version" INTEGER NOT NULL DEFAULT 1,
    "student_id" UUID NOT NULL,
    "course_id" UUID NOT NULL,
    "semester" VARCHAR(20) NOT NULL,
    "attendance_score" NUMERIC(4, 2) CHECK (attendance_score >= 0 AND attendance_score <= 10),
    "midterm_score" NUMERIC(4, 2) CHECK (midterm_score >= 0 AND midterm_score <= 10),
    "final_score" NUMERIC(4, 2) CHECK (final_score >= 0 AND final_score <= 10),
    "status" VARCHAR(30) NOT NULL DEFAULT 'IN_PROGRESS' CHECK (status IN ('IN_PROGRESS', 'PASSED', 'FAILED', 'WITHDRAWN')),
    CONSTRAINT "fk_enrollments_student" FOREIGN KEY ("student_id") REFERENCES "students" ("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "fk_enrollments_course" FOREIGN KEY ("course_id") REFERENCES "courses" ("id") ON DELETE RESTRICT ON UPDATE CASCADE
);
COMMENT ON TABLE "enrollments" IS 'Dang ky hoc phan va bang diem sinh vien';
COMMENT ON COLUMN "enrollments"."id" IS 'Unique surrogate primary key (UUIDv4/v7)';
COMMENT ON COLUMN "enrollments"."created_at" IS 'Timestamp when record was created';
COMMENT ON COLUMN "enrollments"."updated_at" IS 'Timestamp when record was last updated';
COMMENT ON COLUMN "enrollments"."deleted_at" IS 'Soft-delete timestamp; NULL indicates active record';
COMMENT ON COLUMN "enrollments"."version" IS 'Optimistic locking version counter';
COMMENT ON COLUMN "enrollments"."student_id" IS 'Sinh vien tham gia hoc';
COMMENT ON COLUMN "enrollments"."course_id" IS 'Mon hoc dang ky';
COMMENT ON COLUMN "enrollments"."semester" IS 'Hoc ky dang ky (VD: 2026-1)';
COMMENT ON COLUMN "enrollments"."attendance_score" IS 'Diem chuyen can';
COMMENT ON COLUMN "enrollments"."midterm_score" IS 'Diem giua ky';
COMMENT ON COLUMN "enrollments"."final_score" IS 'Diem thi ket thuc hoc phan';
COMMENT ON COLUMN "enrollments"."status" IS 'Trang thai hoan thanh';
DROP TRIGGER IF EXISTS "trg_enrollments_updated_at" ON "enrollments";
CREATE TRIGGER "trg_enrollments_updated_at"
BEFORE UPDATE ON "enrollments"
FOR EACH ROW EXECUTE FUNCTION trigger_set_timestamp();

-- Table: student_audit_logs (Nhat ky kiem toan bat bien ghi lai cac thay doi ho so sinh vien)
CREATE TABLE IF NOT EXISTS "student_audit_logs" (
    "id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "student_id" UUID,
    "action" VARCHAR(50) NOT NULL,
    "changed_by" VARCHAR(100) NOT NULL,
    "old_values" JSONB,
    "new_values" JSONB,
    "ip_address" VARCHAR(45),
    CONSTRAINT "fk_audit_student" FOREIGN KEY ("student_id") REFERENCES "students" ("id") ON DELETE SET NULL ON UPDATE CASCADE
);
COMMENT ON TABLE "student_audit_logs" IS 'Nhat ky kiem toan bat bien ghi lai cac thay doi ho so sinh vien';
COMMENT ON COLUMN "student_audit_logs"."id" IS 'Surrogate primary key';
COMMENT ON COLUMN "student_audit_logs"."created_at" IS 'Thoi diem xay ra su kien';
COMMENT ON COLUMN "student_audit_logs"."student_id" IS 'Sinh vien bi tac dong';
COMMENT ON COLUMN "student_audit_logs"."action" IS 'Loai thao tac: CREATE, UPDATE, DELETE, UPLOAD_AVATAR';
COMMENT ON COLUMN "student_audit_logs"."changed_by" IS 'Tai khoan thuc hien';
COMMENT ON COLUMN "student_audit_logs"."old_values" IS 'Gia tri truoc khi sua';
COMMENT ON COLUMN "student_audit_logs"."new_values" IS 'Gia tri sau khi sua';
COMMENT ON COLUMN "student_audit_logs"."ip_address" IS 'IP client';

-- 5. PERFORMANCE & SEARCH INDEXES

-- Indexes for table: classes
CREATE INDEX IF NOT EXISTS "idx_classes_department_id" ON "classes" ("department_id");

-- Indexes for table: courses
CREATE INDEX IF NOT EXISTS "idx_courses_department_id" ON "courses" ("department_id");

-- Indexes for table: students
CREATE UNIQUE INDEX IF NOT EXISTS "idx_students_student_code" ON "students" ("student_code");
CREATE INDEX IF NOT EXISTS "idx_students_full_name" ON "students" ("full_name");
CREATE INDEX IF NOT EXISTS "idx_students_class_id" ON "students" ("class_id");
CREATE UNIQUE INDEX IF NOT EXISTS "idx_students_email" ON "students" ("email");
CREATE INDEX IF NOT EXISTS "idx_students_active_status" ON "students" ("status") WHERE "deleted_at" IS NULL;

-- Indexes for table: enrollments
CREATE INDEX IF NOT EXISTS "idx_enrollments_student_id" ON "enrollments" ("student_id");
CREATE INDEX IF NOT EXISTS "idx_enrollments_course_id" ON "enrollments" ("course_id");
CREATE INDEX IF NOT EXISTS "idx_enrollments_active_status" ON "enrollments" ("status") WHERE "deleted_at" IS NULL;

-- Indexes for table: student_audit_logs
CREATE INDEX IF NOT EXISTS "idx_student_audit_logs_student_id" ON "student_audit_logs" ("student_id");
CREATE INDEX IF NOT EXISTS "idx_student_audit_logs_old_values_gin" ON "student_audit_logs" USING gin ("old_values");
CREATE INDEX IF NOT EXISTS "idx_student_audit_logs_new_values_gin" ON "student_audit_logs" USING gin ("new_values");


